const source = $('Webhook Tool Request').item.json || {};
const body = source.body || source;
const headers = source.headers || {};
const expectedToken = String($env.MIA_TOOL_GATEWAY_TOKEN || '').trim();
const providedToken = String(headers['x-mia-tool-token'] || headers['X-Mia-Tool-Token'] || '').trim();

if (expectedToken && providedToken !== expectedToken) {
  return [{ json: { ok: false, error: 'Unauthorized tool gateway token.' } }];
}

const tool = String(body.tool || '').trim();
const args = body.args && typeof body.args === 'object' ? body.args : {};
const requestId = String(body.requestId || '').trim();
const originChatId = String(body.chatId || '').trim();
const deliveryMode = String(body.deliveryMode || 'return').trim() || 'return';
const backendChatId = deliveryMode === 'telegram' ? originChatId : '';

function clean(value) {
  return String(value || '').trim();
}

function buildText() {
  switch (tool) {
    case 'weather.get':
      return { workflowKey: 'weather', text: `thời tiết ${clean(args.location)}`.trim() };
    case 'gold.get_price':
      return { workflowKey: 'gold', text: 'giá vàng hôm nay' };
    case 'news.get':
      return { workflowKey: 'news', text: clean(args.topic) ? `tin tức ${clean(args.topic)}` : 'tin tức hôm nay' };
    case 'search.web':
      return { workflowKey: 'search', text: `tìm kiếm ${clean(args.query)}`.trim() };
    case 'calendar.assistant':
      return { workflowKey: 'calendar', text: clean(args.instruction) };
    case 'gmail.assistant':
      return { workflowKey: 'gmail', text: clean(args.instruction) };
    case 'drive.assistant':
      return { workflowKey: 'drive', text: clean(args.instruction) };
    case 'docs.assistant':
      return { workflowKey: 'docs', text: clean(args.instruction) };
    case 'sheets.assistant':
      return { workflowKey: 'sheets', text: clean(args.instruction) };
    case 'shortlink.create': {
      const url = clean(args.url);
      const ttl = clean(args.ttl);
      return { workflowKey: 'shortlink', text: ttl ? `rut gon link ${url} ${ttl}` : `rut gon link ${url}` };
    }
    default:
      return null;
  }
}

if (!tool) {
  return [{ json: { ok: false, error: 'Missing tool name.' } }];
}

const built = buildText();
if (!built || !built.text) {
  return [{ json: { ok: false, error: `Unsupported or invalid tool request: ${tool}` } }];
}

return [{
  json: {
    ok: true,
    tool,
    workflowKey: built.workflowKey,
    text: built.text,
    rawText: built.text,
    chatId: backendChatId,
    originChatId,
    requestId,
    deliveryMode,
    args,
    payload: { tool, args, requestId, originChatId, deliveryMode },
    message: { text: built.text, caption: built.text }
  }
}];

